static Node *
mys_makeAConst(Node *v, int location)
{
	Node *n;

	switch (v->type)
	{
		case T_Float:
			n = mys_makeFloatConst(castNode(Float, v)->fval, location);
			break;

		case T_Integer:
			n = mys_makeIntConst(castNode(Integer, v)->ival, location);
			break;

		case T_String:
		default:
			n = mys_makeStringConst(castNode(String, v)->sval, location);
			break;
	}

	return n;
}

