static ResTarget *
createResTargetWithFunc2Args(char *name, char *funcShemaName, char *funcName, 
                             char *arg1, char *arg2)
{
    ResTarget *resTarget;
    FuncCall *funcCall;
    List *funcNames;
    List *funcArgs;

    resTarget = makeNode(ResTarget);
    if (name != NULL)
    {
        resTarget->name = pstrdup(name);
    }
    else 
    {
        resTarget->name = NULL;
    }
    resTarget->indirection = NIL; 
    funcNames = list_make2(makeString(pstrdup(funcShemaName)), makeString(pstrdup(funcName)));
    funcArgs = NIL;
    if (arg1 != NULL)
    {
        funcArgs = lappend(funcArgs, mys_makeStringConst(pstrdup(arg1), -1));
    }
    else 
    {
        funcArgs = lappend(funcArgs, mys_makeNullAConst(1));
    }
    if (arg2 != NULL)
    {
        funcArgs = lappend(funcArgs, mys_makeStringConst(pstrdup(arg2), -1));
    }
    else 
    {
        funcArgs = lappend(funcArgs, mys_makeNullAConst(1));
    }
    funcCall = makeFuncCall(funcNames, funcArgs, COERCE_EXPLICIT_CALL, -1);
    resTarget->val = (Node *)funcCall;
    resTarget->location = -1; 

    return resTarget;
}

static RangeVar *
createRangeVar(char *schemaName, char *tableName)
{
    RangeVar *rangeVar;

    rangeVar = makeRangeVar(NULL, NULL, -1);
    if (schemaName != NULL)
    {
        rangeVar->schemaname = pstrdup(schemaName);
    }
    else 
    {
        rangeVar->schemaname = pstrdup(get_namespace_name(getCurrentNamespaceOid()));
    }
    rangeVar->relname = pstrdup(tableName);
    rangeVar->inh = true;
    rangeVar->alias = NULL;

    return rangeVar;
}

static void
checkJoinOn(JoinExpr *joinExpr, bool *hasNotOn)
{
    if (IsA(joinExpr->larg, JoinExpr))
    {
        checkJoinOn(castNode(JoinExpr, joinExpr->larg), hasNotOn);
    }
    if (IsA(joinExpr->rarg, JoinExpr))
    {
        checkJoinOn(castNode(JoinExpr, joinExpr->rarg), hasNotOn);
    }

    if (joinExpr->quals == NULL)
    {
        *hasNotOn = true;
    }
}

static void
makeOnClause(Node **expr, JoinExpr *joinExpr)
{
    if (IsA(joinExpr->larg, JoinExpr))
    {
        makeOnClause(expr, castNode(JoinExpr, joinExpr->larg));
    }
    if (IsA(joinExpr->rarg, JoinExpr))
    {
        makeOnClause(expr, castNode(JoinExpr, joinExpr->rarg));
    }

    if (joinExpr->quals != NULL)
    {
        if (*expr != NULL)
        {
            *expr = makeAndExpr(*expr, (Node *)(joinExpr->quals), -1);
        }
        else 
        {
            *expr = joinExpr->quals;
        }

        joinExpr->quals = NULL;
    }
}
